CREATE OR REPLACE FUNCTION public.replace_generated_course(p_course uuid,p_topics jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_topic jsonb; v_id uuid; v_order integer:=0; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM courses WHERE id=p_course AND teacher_id=auth.uid()) THEN RAISE EXCEPTION 'Course owner required'; END IF; IF jsonb_typeof(p_topics)<>'array' OR jsonb_array_length(p_topics)=0 THEN RAISE EXCEPTION 'Empty generated content'; END IF; PERFORM pg_advisory_xact_lock(hashtext(p_course::text)); UPDATE topics SET deleted_at=now() WHERE course_id=p_course AND deleted_at IS NULL; FOR v_topic IN SELECT value FROM jsonb_array_elements(p_topics) LOOP IF coalesce(trim(v_topic->>'title'),'')='' THEN RAISE EXCEPTION 'Topic title required'; END IF; INSERT INTO topics(course_id,order_index,title,summary,objectives,explanation,examples,exercises,exercises_solved,is_test,is_final) VALUES(p_course,v_order,v_topic->>'title',coalesce(v_topic->>'summary',''),coalesce(v_topic->>'objectives',''),coalesce(v_topic->>'explanation',''),coalesce(v_topic->>'examples',''),coalesce(v_topic->>'exercises',''),coalesce(v_topic->>'exercises_solved',''),v_topic->>'title' ~* '^test',v_topic->>'title' ~* 'final') RETURNING id INTO v_id; IF jsonb_typeof(v_topic->'quiz')='array' AND jsonb_array_length(v_topic->'quiz')>0 THEN INSERT INTO quizzes(topic_id,title,questions) VALUES(v_id,'Quiz: '||(v_topic->>'title'),v_topic->'quiz'); END IF; v_order:=v_order+1; END LOOP; UPDATE courses SET ai_processed=true,status='published' WHERE id=p_course; RETURN v_order; END $$;
REVOKE ALL ON FUNCTION public.replace_generated_course(uuid,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.replace_generated_course(uuid,jsonb) TO authenticated;